#include <bits/stdc++.h>
using namespace std;

const int MOD = 1e9 + 7;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<string> words(n);
    for (int i = 0; i < n; i++) cin >> words[i];

    vector<int> seasonal(n, 0);
    for (int i = 0; i < m; i++) {
        int idx;
        cin >> idx;
        seasonal[idx] = 1;
    }

    // adjacency: last char -> word indices
    vector<vector<int>> adj(26);
    for (int i = 0; i < n; i++) {
        adj[words[i].back() - 'a'].push_back(i);
    }

    // dp[mask][last] = number of ways with used seasonal mask, ending at word 'last'
    vector<vector<long long>> dp(1 << m, vector<long long>(n, 0));

    // map seasonal word index to compressed index
    vector<int> seasonalIndex(n, -1);
    int sid = 0;
    for (int i = 0; i < n; i++) {
        if (seasonal[i]) {
            seasonalIndex[i] = sid++;
        }
    }

    // Initialize: start with any word
    for (int i = 0; i < n; i++) {
        int mask = 0;
        if (seasonal[i]) mask = (1 << seasonalIndex[i]);
        dp[mask][i] = 1;
    }

    for (int mask = 0; mask < (1 << m); mask++) {
        for (int last = 0; last < n; last++) {
            if (dp[mask][last] == 0) continue;
            char lastChar = words[last].back();
            for (int nxt : adj[lastChar - 'a']) {
                int newMask = mask;
                if (seasonal[nxt]) {
                    int idx = seasonalIndex[nxt];
                    if (mask & (1 << idx)) continue; // already used
                    newMask = mask | (1 << idx);
                }
                dp[newMask][nxt] = (dp[newMask][nxt] + dp[mask][last]) % MOD;
            }
        }
    }

    long long ans = 0;
    int fullMask = (1 << m) - 1;
    for (int i = 0; i < n; i++) {
        ans = (ans + dp[fullMask][i]) % MOD;
    }

    cout << ans << "\n";
    return 0;
}

