    vector<vector<int>> adj(V), radj(V);
    for (auto [a,b] : edges) { adj[a].push_back(b); radj[b].push_back(a); }

    // dp_out[v] = # paths starting at v not going through seasonal nodes (except v itself at start)
    // dp_in[v] = # paths ending at v not going through seasonal nodes (except v itself at end)
    // For non-seasonal nodes only in intermediate

    // Compute on DAG using topological sort
    vector<long long> dp_out(V, 1), dp_in(V, 1);
    // Topological sort
    vector<int> indeg(V, 0);
    for (auto [a,b] : edges) indeg[b]++;
