    reverse(topo.begin(), topo.end());
    for (int v : topo) for (int u : radj[v]) if (!seasonal.count(u)) dp_in[v] = (dp_in[v] + dp_in[u]) % MOD;

    long long ans = 0;
    for (int s : seasonal) ans = (ans + dp_in[s] * dp_out[s]) % MOD;
    cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

/*
The statement provided is incomplete/ambiguous, so this solution targets the standard
interpretation of this type of problem:

- We are given a dictionary of directed connections between words: word A can be followed by word B.
- We are also given a list of "seasonal" words.
- We must count the number of distinct poems (walks in the directed graph) that use every seasonal
  word exactly once, in the given order of appearance in the poem, while allowing arbitrary
  non-seasonal words in between.
- A seasonal word may appear at the boundary of connections, i.e. it can be the first/last word
  of a segment.
- No seasonal word may appear more than once anywhere in the poem.

Input format assumed:
n m
n dictionary words (strings)
m directed edges: u v   (as strings)
k
k seasonal words (strings)

Output:
number of valid poems modulo 1e9+7

Because the original statement omitted the exact format and precise combinatorial definition,
this is the most reasonable graph-DP interpretation.

Method:
1. Build graph on all words.
2. Mark seasonal words.
3. For each consecutive pair of seasonal words s[i] -> s[i+1], count paths from s[i] to s[i+1]
   that do not pass through any seasonal word except endpoints.
4. Multiply these counts for all adjacent seasonal pairs.
   This counts poems formed by concatenating such valid segments, ensuring each seasonal word
   appears exactly once.

If k == 1, answer is 1 (the poem consisting of that seasonal word, with no extra seasonal words).

Important note:
If the graph contains cycles consisting only of non-seasonal words on a route between seasonal
words, then the number of poems can be infinite. Since the original statement asks for a finite
answer modulo MOD and provides no special handling, we assume the relevant subgraph is a DAG
or otherwise acyclic with respect to valid transitions. We topologically process the allowed
subgraph; if cycles exist, this implementation does not define infinite handling.

*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<string> words(n);
    unordered_map<string, int> id;
    id.reserve(n * 2);

    for (int i = 0; i < n; ++i) {
        cin >> words[i];
        id[words[i]] = i;
    }

    vector<vector<int>> g(n), rg(n);
    for (int i = 0; i < m; ++i) {
        string a, b;
        cin >> a >> b;
        int u = id[a], v = id[b];
        g[u].push_back(v);
        rg[v].push_back(u);
    }

    int k;
    cin >> k;
    vector<int> season(k);
    vector<int> isSeason(n, 0);
    for (int i = 0; i < k; ++i) {
        string s;
        cin >> s;
        season[i] = id[s];
        isSeason[season[i]] = 1;
    }

    if (k == 0) {
        cout << 0 << '\n';
        return 0;
    }
    if (k == 1) {
        cout << 1 << '\n';
        return 0;
    }

    auto count_paths = [&](int src, int dst) -> long long {
        vector<int> allowed(n, 1);
        for (int v = 0; v < n; ++v) {
            if (isSeason[v] && v != src && v != dst) allowed[v] = 0;
        }

        // Restrict to nodes reachable from src and that can reach dst, inside allowed nodes.
        vector<int> vis1(n, 0), vis2(n, 0);
        queue<int> q;

        if (allowed[src]) {
            q.push(src);
            vis1[src] = 1;
        }
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : g[u]) {
                if (allowed[v] && !vis1[v]) {
                    vis1[v] = 1;
                    q.push(v);
                }
            }
        }

        if (allowed[dst]) {
            q.push(dst);
            vis2[dst] = 1;
        }
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : rg[u]) {
                if (allowed[v] && !vis2[v]) {
                    vis2[v] = 1;
                    q.push(v);
                }
            }
        }

        vector<int> nodes;
        nodes.reserve(n);
        vector<int> inSub(n, 0);
        for (int i = 0; i < n; ++i) {
            if (allowed[i] && vis1[i] && vis2[i]) {
                inSub[i] = 1;
                nodes.push_back(i);
            }
        }

        if (!inSub[src] || !inSub[dst]) return 0;

        // Topological sort on induced subgraph.
        vector<int> indeg(n, 0);
        for (int u : nodes) {
            for (int v : g[u]) {
                if (inSub[v]) indeg[v]++;
            }
        }

        queue<int> topoQ;
        for (int u : nodes) if (indeg[u] == 0) topoQ.push(u);

        vector<int> topo;
        topo.reserve(nodes.size());
        while (!topoQ.empty()) {
            int u = topoQ.front(); topoQ.pop();
            topo.push_back(u);
            for (int v : g[u]) {
                if (inSub[v]) {
                    if (--indeg[v] == 0) topoQ.push(v);
                }
            }
        }

        // If cycle exists in relevant subgraph, the problem statement is insufficient to define
        // behavior; we assume acyclic valid input. If not acyclic, return 0 conservatively.
        if ((int)topo.size() != (int)nodes.size()) {
            return 0;
        }

        vector<long long> dp(n, 0);
        dp[src] = 1;
        for (int u : topo) {
            if (!dp[u]) continue;
            for (int v : g[u]) {
                if (inSub[v]) {
                    dp[v] += dp[u];
                    if (dp[v] >= MOD) dp[v] -= MOD;
                }
            }
        }
        return dp[dst];
    };

    long long ans = 1;
    for (int i = 0; i + 1 < k; ++i) {
        long long ways = count_paths(season[i], season[i + 1]);
        ans = (ans * ways) % MOD;
        if (ans == 0) break;
    }

    cout << ans % MOD << '\n';
    return 0;
}

