public class PoemCounter {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt(); // number of words in dictionary
        sc.nextLine();

        String[] words = new String[n];
        for (int i = 0; i < n; i++) {
            words[i] = sc.nextLine().trim();
        }

        int s = sc.nextInt(); // number of seasonal words
        sc.nextLine();

        Set<String> seasonalSet = new HashSet<>();
        for (int i = 0; i < s; i++) {
            seasonalSet.add(sc.nextLine().trim());
        }

        // Map seasonal words to indices
        List<String> seasonalList = new ArrayList<>(seasonalSet);
        int k = seasonalList.size();
        Map<String, Integer> seasonalIndex = new HashMap<>();
        for (int i = 0; i < k; i++) {
            seasonalIndex.put(seasonalList.get(i), i);
        }

        // Adjacency list for all words
        Map<Character, List<Integer>> startCharMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            char c = words[i].charAt(0);
            startCharMap.computeIfAbsent(c, x -> new ArrayList<>()).add(i);
        }

        // Precompute transitions between seasonal words
        int[][] seasonalTransition = new int[k][k];
        for (int i = 0; i < k; i++) {
            String wordA = seasonalList.get(i);
            char lastChar = wordA.charAt(wordA.length() - 1);
            List<Integer> candidates = startCharMap.getOrDefault(lastChar, new ArrayList<>());
            for (int idx : candidates) {
                String wordB = words[idx];
                if (seasonalIndex.containsKey(wordB)) {
                    int j = seasonalIndex.get(wordB);
                    seasonalTransition[i][j] = (seasonalTransition[i][j] + 1) % MOD;
                }
            }
        }

        // DP over subsets: dp[mask][last] = number of ways
        long[][] dp = new long[1 << k][k];
        for (int i = 0; i < k; i++) {
            dp[1 << i][i] = 1; // start with any seasonal word
        }

        for (int mask = 1; mask < (1 << k); mask++) {
            for (int last = 0; last < k; last++) {
                if ((mask & (1 << last)) == 0) continue;
                long ways = dp[mask][last];
                if (ways == 0) continue;
                for (int next = 0; next < k; next++) {
                    if ((mask & (1 << next)) != 0) continue;
                    int trans = seasonalTransition[last][next];
                    if (trans > 0) {
                        dp[mask | (1 << next)][next] = (dp[mask | (1 << next)][next] + ways * trans) % MOD;
                    }
                }
            }
        }

        long result = 0;
        int fullMask = (1 << k) - 1;
        for (int last = 0; last < k; last++) {
            result = (result + dp[fullMask][last]) % MOD;
        }

        System.out.println(result);
        sc.close();
    }
}

