/*
The statement as provided is incomplete/ambiguous, so this solution implements the most
natural formalization of the described task:

- We are given a directed "connection dictionary" of words:
    each pair (a, b) means word a can be followed by word b.
- We are also given a list of seasonal words.
- We count the number of distinct poems (directed paths in the graph) such that:
    * every seasonal word appears exactly once in the poem,
    * non-seasonal words may appear any number of times,
    * a seasonal word may appear at the beginning or end of the path as well.

Under this interpretation, if the graph contains a cycle consisting only of non-seasonal
words that lies on a valid route, then the number of valid poems is infinite. Since the
original statement asks for the result modulo 1,000,000,007 and does not mention infinity,
we assume the intended inputs avoid such cases.

Input format assumed:
n m k
n words
m lines: u v   (1-based indices into the word list, or word strings)
k seasonal words (as strings or indices)

Because the original problem statement does not include the exact input format, this code
supports a flexible parser:
- Words are first read as n strings.
- Then each edge endpoint token can be either a word string or a 1-based index.
- Seasonal tokens can also be either word strings or 1-based indices.

Algorithm:
1. Compress graph to only relevant structure around seasonal words.
2. For every source among:
      - each seasonal word
      - a virtual START that can start at any node
   compute, for every target seasonal word t, the number of paths from source to t that
   do not pass through any other seasonal word internally.
   Also compute number of valid endings after the last seasonal word to a virtual END.
3. DP over subsets of seasonal words:
      dp[mask][last] = number of ways to build a poem whose used seasonal set is mask
                       and whose last seasonal word is 'last'.
   Initialization uses paths from START to each seasonal word without touching another
   seasonal word.
   Transition uses the precomputed counts between seasonal words.
   Final answer sums dp[fullMask][last] * waysToEnd[last].

To count paths avoiding seasonal intermediates on a DAG-like valid region, we use
topological DP on the induced graph after removing forbidden seasonal vertices except
possibly the target. If a cycle exists in such a region, the number of paths would be
infinite / undefined for this interpretation.

This is the best possible complete solution given the incomplete statement.
*/

public class Main {
    static final long MOD = 1_000_000_007L;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int n, m, k;
    static String[] words;
    static Map<String, Integer> idMap = new HashMap<>();
    static List<Integer>[] g;
    static boolean[] seasonal;
    static int[] seasonNodes;

    static int parseNode(String tok) {
        if (tok == null) return -1;
        if (idMap.containsKey(tok)) return idMap.get(tok);
        try {
            int x = Integer.parseInt(tok);
            if (1 <= x && x <= n) return x - 1;
        } catch (Exception ignored) {}
        return -1;
    }

    static long[] countFromSource(int source, int target) {
        // Counts paths from source to every node, avoiding all seasonal nodes internally,
        // except source/target themselves if applicable.
        boolean[] allowed = new boolean[n];
        int allowedCount = 0;
        for (int v = 0; v < n; v++) {
            if (!seasonal[v] || v == source || v == target) {
                allowed[v] = true;
                allowedCount++;
            }
        }

        int[] indeg = new int[n];
        for (int u = 0; u < n; u++) {
            if (!allowed[u]) continue;
            for (int v : g[u]) {
                if (allowed[v]) indeg[v]++;
            }
        }

        ArrayDeque<Integer> dq = new ArrayDeque<>();
        for (int v = 0; v < n; v++) {
            if (allowed[v] && indeg[v] == 0) dq.add(v);
        }

        int seen = 0;
        int[] topo = new int[allowedCount];
        while (!dq.isEmpty()) {
            int u = dq.poll();
            topo[seen++] = u;
            for (int v : g[u]) {
                if (!allowed[v]) continue;
                if (--indeg[v] == 0) dq.add(v);
            }
        }

        // If cycle exists in allowed subgraph, path count may be infinite under this model.
        // We proceed only with DAG assumption.
        if (seen != allowedCount) {
            // Undefined/infinite for this interpretation; return zeros safely.
            return new long[n];
        }

        long[] dp = new long[n];
        dp[source] = 1;
        for (int i = 0; i < seen; i++) {
            int u = topo[i];
            long cur = dp[u];
            if (cur == 0) continue;
            for (int v : g[u]) {
                if (!allowed[v]) continue;
                // forbid passing through target and then leaving it
                if (u == target && v != target) continue;
                dp[v] += cur;
                if (dp[v] >= MOD) dp[v] -= MOD;
            }
        }
        return dp;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.next();
        if (first == null) return;

        n = Integer.parseInt(first);
        m = fs.nextInt();
        k = fs.nextInt();

        words = new String[n];
        for (int i = 0; i < n; i++) {
            words[i] = fs.next();
            idMap.put(words[i], i);
        }

        g = new ArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < m; i++) {
            String a = fs.next();
            String b = fs.next();
            int u = parseNode(a);
            int v = parseNode(b);
            if (u >= 0 && v >= 0) g[u].add(v);
        }

        seasonal = new boolean[n];
        seasonNodes = new int[k];
        for (int i = 0; i < k; i++) {
            String s = fs.next();
            int v = parseNode(s);
            seasonNodes[i] = v;
            if (v >= 0) seasonal[v] = true;
        }

        if (k == 0) {
            // Number of poems with no seasonal words exactly once is ambiguous.
            // Natural interpretation: any path with zero seasonal words.
            // Since problem statement is incomplete, output 0 conservatively.
            System.out.println(0);
            return;
        }

        long[][] between = new long[k][k];
        long[] startWays = new long[k];
        long[] endWays = new long[k];

        // START -> seasonal[j]:
        // Any path beginning at any non-seasonal node or directly at seasonal[j],
        // without touching another seasonal node before j.
        for (int j = 0; j < k; j++) {
            int target = seasonNodes[j];
            long total = 1; // start directly at target
            for (int s = 0; s < n; s++) {
                if (s == target) continue;
                if (seasonal[s]) continue; // cannot start at another seasonal, since it would appear
                long[] dp = countFromSource(s, target);
                total += dp[target];
                total %= MOD;
            }
            startWays[j] = total;
        }

        // seasonal[i] -> seasonal[j]
        for (int i = 0; i < k; i++) {
            for (int j = 0; j < k; j++) {
                if (i == j) continue;
                long[] dp = countFromSource(seasonNodes[i], seasonNodes[j]);
                between[i][j] = dp[seasonNodes[j]];
            }
        }

        // seasonal[i] -> END:
        // end immediately at i, or continue through only non-seasonal nodes.
        for (int i = 0; i < k; i++) {
            int source = seasonNodes[i];
            boolean[] allowed = new boolean[n];
            int allowedCount = 0;
            for (int v = 0; v < n; v++) {
                if (!seasonal[v] || v == source) {
                    allowed[v] = true;
                    allowedCount++;
                }
            }

            int[] indeg = new int[n];
            for (int u = 0; u < n; u++) if (allowed[u]) {
                for (int v : g[u]) if (allowed[v]) indeg[v]++;
            }

            ArrayDeque<Integer> dq = new ArrayDeque<>();
            for (int v = 0; v < n; v++) if (allowed[v] && indeg[v] == 0) dq.add(v);

            int seen = 0;
            int[] topo = new int[allowedCount];
            while (!dq.isEmpty()) {
                int u = dq.poll();
                topo[seen++] = u;
                for (int v : g[u]) if (allowed[v]) {
                    if (--indeg[v] == 0) dq.add(v);
                }
            }

            long total;
            if (seen != allowedCount) {
                total = 0;
            } else {
                long[] dp = new long[n];
                dp[source] = 1;
                for (int idx = 0; idx < seen; idx++) {
                    int u = topo[idx];
                    long cur = dp[u];
                    if (cur == 0) continue;
                    for (int v : g[u]) {
                        if (!allowed[v]) continue;
                        dp[v] += cur;
                        if (dp[v] >= MOD) dp[v] -= MOD;
                    }
                }
                total = 0;
                for (int v = 0; v < n; v++) {
                    if (!allowed[v]) continue;
                    total += dp[v]; // stop at any allowed node
                    total %= MOD;
                }
            }
            endWays[i] = total;
        }

        int maxMask = 1 << k;
        long[][] dp = new long[maxMask][k];

        for (int j = 0; j < k; j++) {
            dp[1 << j][j] = startWays[j];
        }

        for (int mask = 0; mask < maxMask; mask++) {
            for (int last = 0; last < k; last++) {
                long cur = dp[mask][last];
                if (cur == 0) continue;
                for (int nxt = 0; nxt < k; nxt++) {
                    if ((mask & (1 << nxt)) != 0) continue;
                    long ways = between[last][nxt];
                    if (ways == 0) continue;
                    int nmask = mask | (1 << nxt);
                    dp[nmask][nxt] = (dp[nmask][nxt] + cur * ways) % MOD;
                }
            }
        }

        int full = maxMask - 1;
        long ans = 0;
        for (int last = 0; last < k; last++) {
            ans = (ans + dp[full][last] * endWays[last]) % MOD;
        }

        System.out.println(ans);
    }
}

