#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MOD 1000000007

int n, m;
char words[1005][15];
int seasonal[15]; // indices of seasonal words
int is_seasonal[1005];
long long adj[1005][1005]; // direct connections
long long dp_season[15][15]; // ways from seasonal i to j
long long dp[1<<15][15];

int main() {
    scanf("%d %d", &n, &m);
    for (int i = 0; i < n; i++) {
        scanf("%s", words[i]);
        is_seasonal[i] = 0;
    }
    for (int i = 0; i < m; i++) {
        scanf("%d", &seasonal[i]);
        seasonal[i]--; // zero-index
        is_seasonal[seasonal[i]] = 1;
    }

    // direct connections count
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            if (words[i][strlen(words[i])-1] == words[j][0]) {
                adj[i][j] = 1;
            } else {
                adj[i][j] = 0;
            }
        }
    }

    // Floyd-like extension to count ways using only non-seasonal intermediate nodes
    // But we only need between seasonal nodes, so we can do DP per start node.

    for (int s = 0; s < m; s++) {
        int start = seasonal[s];
        long long cnt[1005];
        for (int i = 0; i < n; i++) cnt[i] = 0;
        cnt[start] = 1;

        // Propagate only through non-seasonal nodes
        for (int step = 0; step < n; step++) {
            for (int u = 0; u < n; u++) {
                if (cnt[u] == 0) continue;
                if (u != start && is_seasonal[u]) continue; // cannot pass through other seasonal
                for (int v = 0; v < n; v++) {
                    if (adj[u][v]) {
                        if (v == start) continue;
                        if (v != start && is_seasonal[v]) {
                            // direct to seasonal end, record
                            int endIdx = -1;
                            for (int k = 0; k < m; k++) if (seasonal[k] == v) { endIdx = k; break; }
                            dp_season[s][endIdx] = (dp_season[s][endIdx] + cnt[u]) % MOD;
                        } else {
                            cnt[v] = (cnt[v] + cnt[u]) % MOD;
                        }
                    }
                }
                cnt[u] = 0; // clear after use to avoid reprocessing same node in same step
            }
        }
    }

    // DP over subsets
    int fullMask = (1<<m) - 1;
    for (int i = 0; i < m; i++) {
        dp[1<<i][i] = 1; // start with any seasonal word
    }

    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < m; last++) {
            if (!(mask & (1<<last))) continue;
            if (dp[mask][last] == 0) continue;
            for (int next = 0; next < m; next++) {
                if (mask & (1<<next)) continue;
                if (dp_season[last][next] == 0) continue;
                int newMask = mask | (1<<next);
                dp[newMask][next] = (dp[newMask][next] + dp[mask][last] * dp_season[last][next]) % MOD;
            }
        }
    }

    long long ans = 0;
    for (int i = 0; i < m; i++) {
        ans = (ans + dp[fullMask][i]) % MOD;
    }

    printf("%lld\n", ans);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 1000000007LL

typedef long long ll;

typedef struct {
    int *a;
    int sz, cap;
} Vec;

static void vec_init(Vec *v) {
    v->a = NULL;
    v->sz = 0;
    v->cap = 0;
}

static void vec_push(Vec *v, int x) {
    if (v->sz == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 4;
        v->a = (int*)realloc(v->a, v->cap * sizeof(int));
    }
    v->a[v->sz++] = x;
}

static int cmp_strptr(const void *p1, const void *p2) {
    const char *a = *(const char**)p1;
    const char *b = *(const char**)p2;
    return strcmp(a, b);
}

static int lower_bound_str(char **arr, int n, const char *s) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        int c = strcmp(arr[m], s);
        if (c < 0) l = m + 1;
        else r = m;
    }
    return l;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    char **left = (char**)malloc(N * sizeof(char*));
    char **right = (char**)malloc(N * sizeof(char*));
    char **season = (char**)malloc(M * sizeof(char*));

    char buf1[256], buf2[256];
    char **all = (char**)malloc((2 * N + M) * sizeof(char*));
    int allcnt = 0;

    for (int i = 0; i < N; i++) {
        scanf("%255s %255s", buf1, buf2);
        left[i] = strdup(buf1);
        right[i] = strdup(buf2);
        all[allcnt++] = left[i];
        all[allcnt++] = right[i];
    }

    for (int i = 0; i < M; i++) {
        scanf("%255s", buf1);
        season[i] = strdup(buf1);
        all[allcnt++] = season[i];
    }

    qsort(all, allcnt, sizeof(char*), cmp_strptr);

    char **words = (char**)malloc(allcnt * sizeof(char*));
    int W = 0;
    for (int i = 0; i < allcnt; i++) {
        if (i == 0 || strcmp(all[i], all[i - 1]) != 0) {
            words[W++] = all[i];
        }
    }

    int *L = (int*)malloc(N * sizeof(int));
    int *R = (int*)malloc(N * sizeof(int));
    for (int i = 0; i < N; i++) {
        L[i] = lower_bound_str(words, W, left[i]);
        R[i] = lower_bound_str(words, W, right[i]);
    }

    int *isSeason = (int*)calloc(W, sizeof(int));
    for (int i = 0; i < M; i++) {
        int id = lower_bound_str(words, W, season[i]);
        if (id < W && strcmp(words[id], season[i]) == 0) isSeason[id] = 1;
    }

    Vec *in = (Vec*)malloc(W * sizeof(Vec));
    Vec *out = (Vec*)malloc(W * sizeof(Vec));
    for (int i = 0; i < W; i++) {
        vec_init(&in[i]);
        vec_init(&out[i]);
    }

    for (int i = 0; i < N; i++) {
        vec_push(&out[L[i]], i);
        vec_push(&in[R[i]], i);
    }

    /*
      Interpretation used:
      - Each dictionary pair (a, b) is a directed connection.
      - A poem is a sequence of connections where adjacent connections share a boundary word.
      - Every seasonal word must appear exactly once as a boundary/word in the whole poem.
      - Seasonal words may appear at endpoints too.
      - Non-seasonal words may appear any number of times.

      We count poems that use each seasonal word exactly once, by DP over subsets of seasonal words
      and current ending word.

      State:
        dp[mask][v] = number of valid connection-chains ending at word v,
                      where the set of seasonal words already appeared in the chain is exactly mask.
      Initialization:
        any single edge u->v, provided seasonal occurrences among {u,v} are not duplicated.
      Transition:
        append edge v->to; only the new endpoint "to" is newly introduced as a boundary word
        because v is shared. So only "to" affects seasonal mask, except if chain length was 0
        (handled by initialization).
    */

    int *seasonId = (int*)malloc(W * sizeof(int));
    for (int i = 0; i < W; i++) seasonId[i] = -1;
    int K = 0;
    for (int i = 0; i < W; i++) {
        if (isSeason[i]) seasonId[i] = K++;
    }

    if (K != M) {
        /* duplicate seasonal names in input -> impossible to use each listed exactly once distinctly */
        printf("0\n");
        return 0;
    }

    if (K > 22) {
        /* Safety for memory; problem constraints likely smaller. */
        printf("0\n");
        return 0;
    }

    int S = 1 << K;
    ll *dp = (ll*)calloc((size_t)S * W, sizeof(ll));

    for (int e = 0; e < N; e++) {
        int u = L[e], v = R[e];
        int mask = 0;
        int ok = 1;
        if (isSeason[u]) mask |= 1 << seasonId[u];
        if (isSeason[v]) {
            int b = 1 << seasonId[v];
            if (mask & b) ok = 0; /* same seasonal word at both ends => appears twice in one-edge poem unless same node */
            else mask |= b;
        }
        if (ok) {
            dp[(size_t)mask * W + v] = (dp[(size_t)mask * W + v] + 1) % MOD;
        }
    }

    for (int mask = 0; mask < S; mask++) {
        for (int v = 0; v < W; v++) {
            ll cur = dp[(size_t)mask * W + v];
            if (!cur) continue;
            for (int i = 0; i < out[v].sz; i++) {
                int e = out[v].a[i];
                int to = R[e];
                int nmask = mask;
                if (isSeason[to]) {
                    int b = 1 << seasonId[to];
                    if (mask & b) continue;
                    nmask |= b;
                }
                ll *cell = &dp[(size_t)nmask * W + to];
                *cell += cur;
                if (*cell >= MOD) *cell -= MOD;
            }
        }
    }

    ll ans = 0;
    int full = S - 1;
    for (int v = 0; v < W; v++) {
        ans += dp[(size_t)full * W + v];
        if (ans >= MOD) ans -= MOD;
    }

    printf("%lld\n", ans % MOD);
    return 0;
}

import sys
from collections import defaultdict

MOD = 1_000_000_007

def solve():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])

    idx = 2
    word_to_id = {}
    id_to_word = []
    graph = defaultdict(list)
    seasonal = set()

    for _ in range(n):
        w = input_data[idx]
        idx += 1
        if w not in word_to_id:
            word_to_id[w] = len(word_to_id)
            id_to_word.append(w)
        u = word_to_id[w]

    # read connections
    for _ in range(m):
        a = input_data[idx]
        b = input_data[idx + 1]
        idx += 2
        if a not in word_to_id:
            word_to_id[a] = len(word_to_id)
            id_to_word.append(a)
        if b not in word_to_id:
            word_to_id[b] = len(word_to_id)
            id_to_word.append(b)
        u = word_to_id[a]
        v = word_to_id[b]
        graph[u].append(v)

    k = int(input_data[idx])
    idx += 1
    seasonal_ids = []
    for _ in range(k):
        w = input_data[idx]
        idx += 1
        if w not in word_to_id:
            word_to_id[w] = len(word_to_id)
            id_to_word.append(w)
        sid = word_to_id[w]
        seasonal.add(sid)
        seasonal_ids.append(sid)

    total_nodes = len(word_to_id)
    # dp[mask][last] = number of ways to use seasonal words given by mask and ending at 'last'
    # We'll handle non-seasonal starts and interspersed non-seasonal words

    # Step 1: Precompute reachability from any node to any seasonal node with non-seasonal middle nodes
    from collections import deque

    def bfs(start, targets):
        dist = [-1] * total_nodes
        q = deque([start])
        dist[start] = 0
        while q:
            u = q.popleft()
            for v in graph[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        res = {}
        for t in targets:
            if dist[t] != -1:
                res[t] = dist[t]
        return res

    # Precompute distances between seasonal nodes (via non-seasonal intermediate nodes)
    seasonal_set = set(seasonal_ids)
    dist_between_seasonal = {}
    for s in seasonal_ids:
        dist_between_seasonal[s] = bfs(s, seasonal_set)

    # Precompute distances from non-seasonal nodes to seasonal nodes
    non_seasonal_nodes = [i for i in range(total_nodes) if i not in seasonal_set]
    start_to_seasonal = {}
    for ns in non_seasonal_nodes:
        start_to_seasonal[ns] = bfs(ns, seasonal_set)

    # DP
    k = len(seasonal_ids)
    full_mask = (1 << k) - 1
    dp = [[0] * k for _ in range(1 << k)]

    # Initialize: start from any non-seasonal node and go to first seasonal
    for sidx, sid in enumerate(seasonal_ids):
        for ns in non_seasonal_nodes:
            if sid in start_to_seasonal.get(ns, {}):
                dp[1 << sidx][sidx] = (dp[1 << sidx][sidx] + 1) % MOD

    # Fill DP
    for mask in range(1 << k):
        for last_idx in range(k):
            if not (mask & (1 << last_idx)):
                continue
            if dp[mask][last_idx] == 0:
                continue
            last_sid = seasonal_ids[last_idx]
            for next_idx in range(k):
                if mask & (1 << next_idx):
                    continue
                next_sid = seasonal_ids[next_idx]
                if next_sid in dist_between_seasonal.get(last_sid, {}):
                    new_mask = mask | (1 << next_idx)
                    dp[new_mask][next_idx] = (dp[new_mask][next_idx] + dp[mask][last_idx]) % MOD

    # Sum over all masks that use all seasonal words
    ans = 0
    for last_idx in range(k):
        ans = (ans + dp[full_mask][last_idx]) % MOD

    print(ans % MOD)

if __name__ == "__main__":
    solve()
